const crypto = require('crypto');
const body = $input.item.json.body;
const secret = process.env.N8N_WEBHOOK_SECRET;
if (!secret) throw new Error('N8N_WEBHOOK_SECRET is not configured');
if (Math.abs(Math.floor(Date.now() / 1000) - body.timestamp) > 300) throw new Error('Webhook timestamp expired');
const expected = crypto.createHmac('sha256', secret).update(`${body.timestamp}.${body.nonce}.${body.payloadBase64}`).digest('hex');
if (expected !== body.signature) throw new Error('Webhook signature invalid');
const payload = JSON.parse(Buffer.from(body.payloadBase64, 'base64url').toString('utf8'));
if (!payload.incidentId) throw new Error('incidentId is required');
return [{ json: { ...body, payload } }];

