const crypto = require('crypto');
const secret = process.env.N8N_WEBHOOK_SECRET;
if (!secret) throw new Error('N8N_WEBHOOK_SECRET is not configured');
const payloadBase64 = Buffer.from(JSON.stringify({ incidentId: $json.payload.incidentId, status: 'delivered' })).toString('base64url');
const timestamp = Math.floor(Date.now() / 1000);
const nonce = crypto.randomBytes(16).toString('hex');
const signature = crypto.createHmac('sha256', secret).update(`${timestamp}.${nonce}.${payloadBase64}`).digest('hex');
return [{ json: { deliveryId: $json.deliveryId, timestamp, nonce, payloadBase64, signature, payload: { incidentId: $json.payload.incidentId, status: 'delivered' } } }];
